package cmd
import("fmt";"github.com/spf13/cobra")
func newMigrateCommand(d *dependencies)*cobra.Command{var src string;var force,del bool;c:=&cobra.Command{Use:"migrate",Short:"Import legacy JSON profiles",Args:cobra.NoArgs,RunE:func(c *cobra.Command,_ []string)error{r,e:=d.app.Migrate(c.Context(),src,force,del);if e!=nil{return e};if len(r)==0{_,e=fmt.Fprintln(c.OutOrStdout(),"No legacy profile files found.");return e};bad:=false;for _,v:=range r{if v.Err!=nil{bad=true;fmt.Fprintf(c.ErrOrStderr(),"[FAIL] %s: %v\n",v.Profile,v.Err)}else{fmt.Fprintf(c.OutOrStdout(),"[OK] %s: %s\n",v.Profile,v.Status)}};if bad{return fmt.Errorf("one or more profiles could not be migrated")};return nil}};c.Flags().StringVar(&src,"source",d.config.BaseDir,"source directory");c.Flags().BoolVarP(&force,"force","f",false,"overwrite");c.Flags().BoolVar(&del,"delete-source",false,"delete verified sources");return c}
